eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   projects: () => (/* binding */ projects)\n/* harmony export */ });\nconst projects = [\n    {\n        id: 2,\n        title: \"AI DevOps Agent\",\n        subtitle: \"Autonomous Code Analysis Engine\",\n        description: \"An autonomous AI agent that clones GitHub repositories, runs comprehensive automated analysis — linting, security scans, tests — and generates intelligent AI-powered reports.\",\n        longDescription: \"The AI DevOps Agent operates as a fully autonomous pipeline. Given a GitHub repository URL, it clones the codebase, runs language-appropriate linters, executes Bandit and dependency vulnerability scans, runs test suites, and aggregates all results. It then feeds the analysis data into an LLM that generates a human-readable report covering code quality, security posture, test coverage, and actionable recommendations. This dramatically reduces the friction of code review and enables continuous quality monitoring without manual effort.\",\n        tech: [\n            \"Python\",\n            \"LangChain\",\n            \"Git API\",\n            \"Bandit\",\n            \"AST Analysis\",\n            \"LLMs\"\n        ],\n        features: [\n            \"Fully autonomous GitHub repo cloning and analysis\",\n            \"Multi-language linting and static analysis\",\n            \"Security vulnerability scanning with Bandit\",\n            \"Automated test suite execution\",\n            \"LLM-generated intelligent insight reports\",\n            \"Dependency CVE detection\"\n        ],\n        category: \"DevOps\",\n        accentColor: \"#f472b6\",\n        gradientFrom: \"#db2777\",\n        gradientTo: \"#a855f7\",\n        icon: \"🤖\"\n    },\n    {\n        id: 3,\n        title: \"BrokeNoMore\",\n        subtitle: \"Smart Expense Tracker\",\n        description: \"A clean, intuitive financial tracking web app that helps users record daily expenses, monitor savings goals, and visualize spending patterns over time.\",\n        longDescription: \"BrokeNoMore provides a modern, minimalist approach to personal finance management. Users can log expenses by category, set monthly budgets, and track savings goals with progress indicators. The app offers visual analytics — spending heatmaps, category breakdowns, and trend charts — to surface insights that drive better financial habits. The responsive design ensures a seamless experience across devices, and local-first data handling ensures user privacy. The project demonstrates full-stack capabilities with a polished, user-centric design approach.\",\n        tech: [\n            \"React\",\n            \"Node.js\",\n            \"Express\",\n            \"MongoDB\",\n            \"Chart.js\",\n            \"Tailwind CSS\"\n        ],\n        features: [\n            \"Daily expense recording with smart categories\",\n            \"Savings goal tracking with progress visualization\",\n            \"Spending pattern analytics and charts\",\n            \"Monthly budget setting and alerts\",\n            \"Responsive mobile-first design\",\n            \"Local-first data privacy\"\n        ],\n        category: \"Web\",\n        accentColor: \"#60a5fa\",\n        gradientFrom: \"#2563eb\",\n        gradientTo: \"#7c3aed\",\n        icon: \"💳\"\n    },\n    {\n        id: 4,\n        title: \"FunDaMentals\",\n        subtitle: \"Gamified Java Learning Platform\",\n        description: \"An interactive Java learning platform that teaches programming fundamentals through engaging mini-games, quizzes, and challenges with user authentication and progress tracking.\",\n        longDescription: \"FunDaMentals transforms Java programming education through gamification. The MVC-architected platform features user authentication, a curriculum of bite-sized programming concepts, interactive coding exercises, and mini-games that challenge users to apply what they've learned. The quest system creates a sense of progression — users earn badges, unlock new modules, and compete on leaderboards. Each concept is taught through a theory → example → practice → quiz loop that maximizes retention. The platform is designed for beginners and intermediate learners wanting to master Java fundamentals in an engaging environment.\",\n        tech: [\n            \"Java\",\n            \"MVC Architecture\",\n            \"JavaFX\",\n            \"JDBC\",\n            \"MySQL\",\n            \"Game Design\"\n        ],\n        features: [\n            \"User authentication and profile management\",\n            \"Structured curriculum with progressive difficulty\",\n            \"Interactive mini-games for concept reinforcement\",\n            \"Quiz system with instant feedback\",\n            \"Badge and achievement system\",\n            \"Progress tracking and leaderboards\"\n        ],\n        category: \"Education\",\n        accentColor: \"#a78bfa\",\n        gradientFrom: \"#7c3aed\",\n        gradientTo: \"#ec4899\",\n        icon: \"🎮\"\n    },\n    {\n        id: 5,\n        title: \"Customer Churn Prediction System\",\n        subtitle: \"ML-Powered Retention Analytics\",\n        description: \"A machine learning project that predicts whether customers are likely to leave a service, using behavioral data to help businesses take proactive retention action.\",\n        longDescription: \"Customer churn is one of the costliest challenges businesses face. This system tackles it head-on by analyzing historical customer behavior — activity patterns, engagement metrics, and usage signals — to train a predictive ML model that outputs churn probability scores. Multiple classification algorithms are benchmarked (Logistic Regression, Random Forest, XGBoost) to identify the best performer. The model integrates with a visualization layer that surfaces at-risk customer segments and highlights key churn drivers, enabling data-backed retention decisions before customers are lost.\",\n        tech: [\n            \"Python\",\n            \"Scikit-learn\",\n            \"XGBoost\",\n            \"Pandas\",\n            \"Matplotlib\",\n            \"Machine Learning\"\n        ],\n        features: [\n            \"Churn probability prediction per customer\",\n            \"Customer behavior data analysis and feature engineering\",\n            \"Multi-model benchmarking for best accuracy\",\n            \"Data visualization of at-risk segments\",\n            \"Key churn driver identification\",\n            \"Actionable retention insights for businesses\"\n        ],\n        category: \"AI/ML\",\n        accentColor: \"#f59e0b\",\n        gradientFrom: \"#d97706\",\n        gradientTo: \"#ef4444\",\n        icon: \"📉\"\n    },\n    {\n        id: 6,\n        title: \"Facemoji\",\n        subtitle: \"Facial Expression Emoji Generator\",\n        description: \"A computer vision project that detects facial expressions in real time and maps them to corresponding emojis using deep learning emotion classification.\",\n        longDescription: \"Facemoji bridges the gap between human expression and digital communication. Using real-time computer vision, the system captures facial landmarks from a webcam feed, processes them through a deep learning classification model trained on emotion datasets, and instantly generates the matching emoji for each detected expression. The pipeline achieves fast inference suitable for live video applications. Emotions such as happiness, sadness, surprise, anger, and neutral states are classified with high accuracy, making the system both technically impressive and practically engaging — ideal for interactive applications, accessibility tools, and human-computer interaction research.\",\n        tech: [\n            \"Python\",\n            \"OpenCV\",\n            \"Deep Learning\",\n            \"TensorFlow\",\n            \"Computer Vision\",\n            \"CNN\"\n        ],\n        features: [\n            \"Real-time facial expression detection from webcam\",\n            \"Multi-class emotion classification (7 expressions)\",\n            \"Instant emoji mapping per detected emotion\",\n            \"Deep learning CNN model for high accuracy\",\n            \"Live video processing pipeline\",\n            \"Interactive visual output overlay\"\n        ],\n        category: \"AI/ML\",\n        accentColor: \"#f472b6\",\n        gradientFrom: \"#db2777\",\n        gradientTo: \"#f97316\",\n        icon: \"😊\",\n        github: \"https://github.com/Jayani15/Acm_sig_AI/tree/master/Facemoji\"\n    },\n    {\n        id: 7,\n        title: \"YOLO Medical Insurance Detection\",\n        subtitle: \"Object Detection for Healthcare\",\n        description: \"A deep learning project using YOLO to detect and analyze medical insurance related objects in images, building a robust image-based detection pipeline for healthcare data.\",\n        longDescription: \"This project applies cutting-edge YOLO (You Only Look Once) object detection to the healthcare domain. The system is trained on a medical-related dataset to identify and localize insurance documents, medical artifacts, and relevant visual elements in images with high speed and precision. The YOLO architecture enables real-time inference, making it suitable for automated document processing, claims verification, and healthcare data analysis workflows. The project demonstrates solid understanding of object detection pipelines: dataset preparation, anchor configuration, model training, evaluation with mAP metrics, and inference optimization.\",\n        tech: [\n            \"Python\",\n            \"YOLO\",\n            \"OpenCV\",\n            \"Computer Vision\",\n            \"Deep Learning\",\n            \"PyTorch\"\n        ],\n        features: [\n            \"Real-time object detection using YOLO architecture\",\n            \"Medical insurance document and object recognition\",\n            \"Custom dataset training and annotation\",\n            \"High-speed inference pipeline\",\n            \"mAP-based model evaluation\",\n            \"Image-based detection and analysis workflow\"\n        ],\n        category: \"AI/ML\",\n        accentColor: \"#34d399\",\n        gradientFrom: \"#059669\",\n        gradientTo: \"#0ea5e9\",\n        icon: \"🏥\",\n        github: \"https://github.com/Jayani15/Acm_sig_AI/tree/master/MedicalInsur\"\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./data/projects.ts\n");

